cat > /tmp/claude/check.mjs <<'EOF'
import { chromium } from 'playwright';
const base='http://127.0.0.1:4173';
const pages=['/','/products.html','/pricing.html','/orders.html','/contact.html','/about.html'];
const browser=await chromium.launch();
for (const vp of [{width:1280,height:800,n:'desktop'},{width:390,height:844,n:'phone'}]) {
  for (const url of pages) {
    const ctx=await browser.newContext({viewport:{width:vp.width,height:vp.height}});
    const page=await ctx.newPage();
    const errors=[], failed=[];
    page.on('console',m=>{if(m.type()==='error') errors.push(m.text())});
    page.on('pageerror',e=>errors.push('pageerror: '+e.message));
    page.on('requestfailed',r=>failed.push(r.url()+' '+r.failure()?.errorText));
    await page.goto(base+url,{waitUntil:'networkidle'});
    await page.evaluate(()=>document.fonts.ready);
    const info=await page.evaluate(()=>({
      scrollW: document.documentElement.scrollWidth,
      clientW: document.documentElement.clientWidth,
      font: getComputedStyle(document.body).fontFamily,
      fontLoaded: [...document.fonts].map(f=>f.family+':'+f.status),
      imgs: [...document.images].map(i=>({src:i.currentSrc.split('/').pop(),w:i.naturalWidth,h:i.naturalHeight,disp:i.getBoundingClientRect().width})),
      overflowing: [...document.querySelectorAll('body *')].filter(el=>{const r=el.getBoundingClientRect();return r.right>document.documentElement.clientWidth+1||r.left<-1}).slice(0,6).map(el=>el.tagName+'.'+el.className+' '+Math.round(el.getBoundingClientRect().left)+'..'+Math.round(el.getBoundingClientRect().right)),
    }));
    console.log(`\n${vp.n} ${url} scrollW=${info.scrollW} clientW=${info.clientW} font=${info.font}`);
    console.log(' fonts:',info.fontLoaded.join(', '));
    if(errors.length) console.log(' ERRORS:',errors);
    if(failed.length) console.log(' FAILED:',failed);
    if(info.imgs.some(i=>!i.w||!i.h)) console.log(' BROKEN IMGS:',info.imgs.filter(i=>!i.w||!i.h));
    if(info.overflowing.length) console.log(' OVERFLOW:',info.overflowing);
    await ctx.close();
  }
}
await browser.close();
EOF
