import { chromium } from 'playwright';
const base='http://127.0.0.1:4173';
const browser=await chromium.launch();
const widths=[320,360,390,414,600,719,720,721,768,800,900,1024,1100,1280,1440];
const pages=['/','/products.html','/pricing.html','/orders.html','/contact.html','/about.html'];
for (const w of widths) {
  const ctx=await browser.newContext({viewport:{width:w,height:900}});
  const page=await ctx.newPage();
  for (const url of pages) {
    await page.goto(base+url);
    await page.evaluate(()=>document.fonts.ready);
    const r=await page.evaluate(()=>{
      const cw=document.documentElement.clientWidth;
      const bad=[...document.querySelectorAll('body *')].map(el=>{
        const b=el.getBoundingClientRect();
        return {el, b};
      }).filter(({el,b})=> b.width>0 && (b.right>cw+1||b.left<-1))
        .filter(({el})=> !el.closest('.table-wrap')) // intentional horizontal scroll
        .slice(0,5).map(({el,b})=>el.tagName+'.'+(el.className||'')+` [${Math.round(b.left)},${Math.round(b.right)}]`);
      // detect overlapping siblings in flex/grid rows? skip
      return {cw, sw:document.documentElement.scrollWidth, bad};
    });
    if (r.sw>r.cw || r.bad.length) console.log(w,url,'scroll',r.sw,'>',r.cw,'overflow:',r.bad);
  }
  await ctx.close();
}
// interactive states screenshots
for (const [name,w,h,act] of [
  ['menu-phone',390,844,async p=>{await p.click('.nav-toggle');}],
  ['modal-phone',390,844,async p=>{await p.goto(base+'/orders.html');await p.click('[data-order]');}],
  ['modal-desktop',1280,800,async p=>{await p.goto(base+'/orders.html');await p.click('[data-order]');}],
  ['contact-errors',390,844,async p=>{await p.goto(base+'/contact.html');await p.click('button[type=submit]');}],
]) {
  const ctx=await browser.newContext({viewport:{width:w,height:h}});
  const p=await ctx.newPage();
  await p.goto(base+(name.startsWith('menu')?'/':''));
  await act(p);
  await p.waitForTimeout(150);
  await p.screenshot({path:`visual-report/analysis/${name}.png`,fullPage:name!=='menu-phone'});
  await ctx.close();
  console.log('shot',name);
}
await browser.close();
EOF
